import { describe, it, expect } from "vitest";

describe("Claim Office", () => {
  // ===== Premium from item base values =====
  it.todo("should quote a single sword -- premium 105 G (100 base + 5 fee)");
  it.todo("should quote a single amulet -- premium 65 G (60 base + 5 fee)");
  it.todo("should quote a single staff -- premium 85 G (80 base + 5 fee)");
  it.todo("should quote a single potion -- premium 45 G (40 base + 5 fee)");
  it.todo("should quote a single rune -- premium 30 G (25 base + 5 fee)");
  it.todo("should quote a single moonstone -- premium 30 G (25 base + 5 fee)");
  it.todo("should quote an empty item list -- premium 5 G (only the fee)");

  // ===== Building block of 3 alike components =====
  it.todo("should quote 2 runes -- base premium 50 G");
  it.todo("should quote 3 runes -- base premium 60 G (block applies)");
  it.todo("should quote 4 runes -- base premium 100 G (no block, requires exactly 3)");
  it.todo("should quote 7 runes -- base premium 175 G");
  it.todo("should quote 2 runes + 1 moonstone -- base premium 75 G (no block: different types)");
  it.todo("should quote 3 runes + 3 moonstones -- base premium 120 G (two separate blocks)");

  // ===== Modifier scope on multi-item policies =====
  it.todo("should apply cursed surcharge to cursed item only -- cursed sword + plain amulet -> 210 G before fee");

  // ===== Modifier thresholds =====
  it.todo("should apply loyalty discount at exactly 2 years with MHPCO");
  it.todo("should apply high-enchantment surcharge at exactly enchantment 5");
  it.todo("should apply both curse and high-enchantment surcharges when cursed with exactly enchantment 5");
  it.todo("should not apply high-enchantment surcharge at enchantment 4");
  it.todo("should not apply curse surcharge when not cursed");

  // ===== Integration: newcomer with a cursed sword =====
  it.todo("should quote newcomer cursed sword (0 years, no prior contract, steel, enchantment 3) -- premium 165 G");

  // ===== Integration: long-standing customer's second contract =====
  it.todo("should quote 3-year customer second contract cursed sword (enchantment 7) -- premium 160 G");

  // ===== Multiple items of same type =====
  it.todo("should compute insurance sum and cap for two swords -- sum 2000 G, cap 4000 G");

  // ===== Cap exhaustion =====
  it.todo("should compute insurance sum and cap for a sword + amulet -- sum 1600 G, cap 3200 G");
  it.todo("should compute cap based on unmodified insurance value -- cursed sword cap 2000 G");
  it.todo("should compute insurance sum for a sword + 3 runes block -- sum 1750 G");
  it.todo("should pay out first claim 1400 G leaving cap 600 G, then second claim 600 G leaving cap 0 G");

  // ===== Rounding in MHPCO's favor =====
  it.todo("should round premium 197.5 G up -- 198 G");
  it.todo("should round payout 350.5 G down -- 350 G");

  // ===== Claim: standard reimbursement (no special clauses) =====
  it.todo("should pay out regular steel sword (enchantment 3), damage 500 G -- payout 400 G");
  it.todo("should pay out a rune, damage 200 G -- payout 100 G");

  // ===== Deductible per damage event =====
  it.todo("should apply deductible once per damaged item -- dragon attack both sword (500 G) and amulet (300 G) -> payout 600 G");

  // ===== Enchantment threshold vs. dragon material =====
  it.todo("should pay out dragon-material sword (enchantment 9), damage 1000 G -- payout 400 G (50% wins)");
  it.todo("should pay out dragon-material sword (enchantment 5), damage 800 G -- payout 700 G (full reimbursement)");
  it.todo("should pay out steel sword (enchantment 9), damage 1000 G -- payout 400 G (50% only)");

  // ===== Modifier thresholds for claims =====
  it.todo("should pay out dragon-material sword with exactly enchantment 8, damage 1000 G -- payout 400 G");

  // ===== Edge cases: errors =====
  it.todo("should exit with non-zero status and stderr for a quote with an unknown item type");
  it.todo("should exit with non-zero status and stderr for a claim on an item not part of the policy");
  it.todo("should exit with non-zero status and stderr for a claim with a damage amount of -200");
  it.todo("should exit with non-zero status and stderr for a claim with more damages of a type than insured");
});

