```typescript
export interface QuoteItem {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface Customer {
  yearsWithMHPCO: number;
}

export function quote(customer: Customer, items: QuoteItem[]): number {
  const base = items.reduce((sum, item) => sum + basePremium(item), 0);
  return Math.ceil(base + 5);
}

function basePremium(item: QuoteItem): number {
  if (item.type === "sword") return 100;
  return 0;
}
```

