input.content:
export interface QuoteItem {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface Customer {
  yearsWithMHPCO: number;
}

const itemBaseValues: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const itemInsuranceValues: Record<string, number> = {
  sword: 1000,
  amulet: 600,
  staff: 800,
  potion: 400,
  rune: 250,
  moonstone: 250,
};

export function insuranceSum(items: QuoteItem[]): number {
  return items.reduce(
    (sum, item) => sum + (itemInsuranceValues[item.type] ?? 0),
    0
  );
}

export function itemBasePremium(items: QuoteItem[]): number {
  const total = items.reduce(
    (sum, item) => sum + (itemBaseValues[item.type] ?? 0),
    0
  );
  return total - blockDiscount(items);
}

function blockDiscount(items: QuoteItem[]): number {
  const componentTypes = ["rune", "moonstone"];
  let discount = 0;
  for (const type of componentTypes) {
    const count = items.filter((item) => item.type === type).length;
    if (count === 3) discount += 15;
  }
  return discount;
}

export function itemPremium(items: QuoteItem[]): number {
  const base = itemBasePremium(items);
  const adjustments = items.reduce(
    (sum, item) => sum + itemAdjustment(item),
    0
  );
  return base + adjustments;
}

function itemAdjustment(item: QuoteItem): number {
  const base = itemBaseValues[item.type] ?? 0;
  let adjustment = 0;
  if (item.cursed) adjustment += base * 0.5;
  if ((item.enchantment ?? 0) >= 5) adjustment += base * 0.3;
  return adjustment;
}

export function quote(
  customer: Customer,
  items: QuoteItem[],
  priorContracts = 0
): number {
  const base = itemBasePremium(items);
  const itemTotal = itemPremium(items);
  let adjusted = itemTotal;
  if (priorContracts >= 1) adjusted -= base * 0.15;
  if (customer.yearsWithMHPCO >= 2) adjusted -= base * 0.2;
  adjusted += base * 0.1;
  return Math.ceil(adjusted + 5);
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface Incident {
  cause?: string;
  damages: Damage[];
}

export interface Policy {
  items: QuoteItem[];
  insuranceSum: number;
  remainingCap: number;
}

export function createPolicy(items: QuoteItem[]): Policy {
  const sum = insuranceSum(items);
  return { items, insuranceSum: sum, remainingCap: sum * 2 };
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

export function claim(policy: Policy, incident: Incident): ClaimResult {
  const availableItems = [...policy.items];
  let desired = 0;
  for (const damage of incident.damages) {
    if (damage.amount < 0) {
      throw new Error(`negative damage amount: ${damage.amount}`);
    }
    const index = availableItems.findIndex(
      (item) => item.type === damage.itemType
    );
    if (index === -1) {
      throw new Error(
        `damage references item not in policy: ${damage.itemType}`
      );
    }
    const item = availableItems.splice(index, 1)[0];
    const baseInsurance = itemInsuranceValues[item.type] ?? 0;
    const factor =
      (item.enchantment ?? 0) >= 8 ? 0.5 : item.material === "dragon" ? 1 : 1;
    const reimbursement = baseInsurance === 0 ? 0 : factor * damage.amount;
    desired += Math.max(0, reimbursement - 100);
  }
  const payout = Math.min(policy.remainingCap, Math.floor(desired));
  policy.remainingCap -= payout;
  return { payout, remainingCap: policy.remainingCap };
}

