export function quote(
  customer: Customer,
  items: QuoteItem[],
  priorContracts = 0
): number {
  for (const item of items) {
    if (!(item.type in itemBaseValues)) {
      throw new Error(`unknown item type: ${item.type}`);
    }
  }
  const base = itemBasePremium(items);
  const itemTotal = itemPremium(items);
  let adjusted = itemTotal;
  if (priorContracts >= 1) adjusted -= base * 0.15;
  if (customer.yearsWithMHPCO >= 2) adjusted -= base * 0.2;
  adjusted += base * 0.1;
  return Math.ceil(adjusted + 5);
}

